SHARED_JS_CONSTS = {"board-text.js": ["VAR_NEEDS_CONTEXT", "MV_POW", "MV_NOUN"],
                    "speech-text.js": ["FRAC_WORDS"],
                    "voice.js": ["ttsAudio"]}
