def part3dc_render_is_a_job():
    print("\nPART 3dc — the render is a job, not a request (build kq)")
    import time as _t_
    import types as _ty_
    here = os.path.dirname(os.path.abspath(__file__))
    with open(os.path.join(here, "main.py"), encoding="utf-8") as fh:
        msrc = fh.read()
    with open(os.path.join(here, "static", "admin.html"), encoding="utf-8") as fh:
        adm = fh.read()
    admcode = code_only(adm)

    # ---- the shape of the fix, read out of the source -----------------------
    check("kq: there is ONE lock guarding the render job",
          "_PREWARM_STATE_LOCK = threading.Lock()" in msrc,
          "two overlapping prewarm jobs paying twice for the same lines is what "
          "emptied Jim's ElevenLabs credits; nothing in the code prevented it")
    check("kq: the render runs on a background thread, not the request thread",
          "threading.Thread(target=_prewarm_worker" in msrc,
          "a whole-course render is hundreds of serial ElevenLabs calls -- held "
          "inside one HTTP request it outlives Render's proxy timeout")
    check("kq: the endpoint hands off and returns, it no longer renders inline",
          "job = _prewarm_start(todo, already, body.lesson, bool(body.force))" in msrc
          and "for say in todo:" not in msrc.split(
              '@app.post("/api/admin/script-prewarm")')[1].split(
              '@app.post("/api/admin/script-prewarm-status")')[0],
          "the render loop must live in the worker, not the handler")
    check("kq: there is a status endpoint to poll",
          '@app.post("/api/admin/script-prewarm-status")' in msrc, "")
    check("kq: a job still marked running at boot is recovered as INTERRUPTED",
          "_prewarm_recover_record()" in msrc
          and 'rec["state"] = "interrupted"' in msrc,
          "a redeploy kills the thread; without this the page comes back clean and "
          "the dead job is invisible")
    check("kq: the admin page keeps the HTTP status in its error text",
          '" (HTTP " + r.status + ")"' in admcode,
          '"Request failed." threw away the one number that identifies the cause')
    check("kq: the admin page polls the job instead of awaiting the render",
          "async function jobWatch(" in admcode
          and '"/api/admin/script-prewarm-status"' in admcode, "")
    check("kq: both SPENDS buttons watch the job",
          admcode.count("jobWatch(") >= 3,
          "spRun, caRender and the on-load check")

    # ---- and now the behaviour, run for real against a stubbed ElevenLabs ----
    import main as _m
    key = os.environ.get("FORUM_MOD_KEY") or "TESTKEY"
    os.environ["FORUM_MOD_KEY"] = key
    _m.FORUM_MOD_KEY = key
    old_key, old_httpx = _m.ELEVEN_API_KEY, _m.httpx
    _m.ELEVEN_API_KEY = "stub-key-no-network"

    mp3 = None
    for p in _m._TTS_CACHE_DIR.glob("*.mp3"):
        mp3 = p.read_bytes()
        break
    if mp3 is None:
        # A real MPEG-1 Layer III CBR 44100/128k mono stream. It must be genuinely
        # valid: _tts_cache_store REFUSES a damaged clip, so a fake one would make
        # this part measure the refusal path instead of the job.
        _FR = 144 * 128000 // 44100
        mp3 = (b"\xff\xfb\x90\xc4" + b"\x00" * (_FR - 4)) * 30

    class _Resp:
        status_code = 200
        content = mp3

    def _slow_post(url, **kw):
        _t_.sleep(0.02)                  # slow enough that the lock has work to refuse
        return _Resp()

    _m.httpx = _ty_.SimpleNamespace(post=_slow_post)
    _m._PREWARM_JOB = {}
    try:
        from fastapi.testclient import TestClient
        c = TestClient(_m.app)
        lesson = _m.lessonscripts.LESSONS[0]["id"]

        t0 = _t_.time()
        r = c.post("/api/admin/script-prewarm",
                   json={"key": key, "lesson": lesson, "force": True})
        elapsed = _t_.time() - t0
        j = r.json()
        check("kq: the render POST answers in well under a second",
              r.status_code == 200 and elapsed < 2.0,
              f"{elapsed:.2f}s status={r.status_code}")
        check("kq: it reports a started job, not a finished render",
              j.get("started") is True and j.get("state") == "running"
              and j.get("job_id"), j)

        r2 = c.post("/api/admin/script-prewarm",
                    json={"key": key, "lesson": lesson, "force": True})
        check("⭐ kq: a SECOND render while one runs is refused with 409",
              r2.status_code == 409, r2.status_code)
        check("kq: and the refusal says why, in the words that cost Jim money",
              "TWICE" in (r2.json().get("detail") or ""), r2.json())

        saw_partial, st = False, {}
        for _ in range(400):
            st = c.post("/api/admin/script-prewarm-status", json={"key": key}).json()
            d = st["job"].get("done", 0)
            if 0 < d < j["to_render"]:
                saw_partial = True
            if not st.get("running"):
                break
            _t_.sleep(0.05)
        check("kq: status reports progress WHILE it runs", saw_partial,
              "a progress bar that only ever reads 0 then 100 is not progress")
        check("kq: the job finishes and every line is rendered",
              st.get("state", "").startswith("done")
              and st["job"]["done"] == j["to_render"], st.get("job"))

        # dry_run must be exactly as it was: free, synchronous, no job
        _m._PREWARM_JOB = {}
        d = c.post("/api/admin/script-prewarm",
                   json={"key": key, "dry_run": True}).json()
        check("kq DO NO HARM: dry_run still answers in the same request",
              d.get("dry_run") is True, d)
        check("kq DO NO HARM: dry_run starts no job and spends nothing",
              not _m._PREWARM_JOB, _m._PREWARM_JOB)

        # the interrupted record, which is the whole point of writing it down
        _m._prewarm_write_record({"id": "x", "state": "running", "done": 210,
                                  "total": 354, "lesson": "(whole course)"})
        _m._prewarm_recover_record()
        rec = _m._prewarm_read_record()
        check("⭐ kq: a job killed by a restart is recovered as interrupted, "
              "with how far it got",
              rec.get("state") == "interrupted" and rec.get("done") == 210, rec)
        check("kq: and it says re-running resumes rather than paying twice",
              "picks up" in (rec.get("note") or ""), rec.get("note"))
    finally:
        _m.httpx = old_httpx
        _m.ELEVEN_API_KEY = old_key
        _m._PREWARM_JOB = {}
        try:
            _m._PREWARM_RECORD.unlink()
        except Exception:
            pass


def part3dd_the_cache_can_keep_it():
    print("\nPART 3dd — the render refuses to pay for clips the cache will delete (build lb)")
    import time as _t_
    import types as _ty_
    here = os.path.dirname(os.path.abspath(__file__))
    with open(os.path.join(here, "main.py"), encoding="utf-8") as fh:
        msrc = fh.read()
    with open(os.path.join(here, "static", "admin.html"), encoding="utf-8") as fh:
        adm = fh.read()
    admcode = code_only(adm)

    check("lb: the render is guarded by the cache projection",
          "_proj = _tts_cache_projection(sum(len(t) for t in todo))" in msrc
          and 'if not _proj["fits"] and not body.over_cap_ok:' in msrc,
          "the projection existed from build ke and NOTHING EVER REFUSED -- so once "
          "the course outgrew the cap, every render paid for clips the evictor "
          "deleted minutes later")
    check("lb: the refusal names the env var and a number to set",
          "TTS_CACHE_MAX_MB={_need}" in msrc,
          "a refusal that does not say what to change is a wall, not a fix")
    check("lb: Jim can still override it deliberately",
          "over_cap_ok: bool = False" in msrc, "")
    check("⭐ lb: the admin page PRINTS the cache line (the unread field)",
          "Voice cache: " in admcode and "projected_total_mb" in admcode,
          "the endpoint returned used/cap/projected since build ke and this page "
          "never displayed one of them -- the symptom was invisible for six builds")
    check("lb: and the over-cap render re-arms as a deliberate second click",
          "over_cap_ok: overCap" in admcode and "_spOverCap" in admcode,
          "same two-click money pattern as kl's per-lesson re-render")

    # ---- and now the behaviour, against a cap too small for the course --------
    import main as _m
    key = os.environ.get("FORUM_MOD_KEY") or "TESTKEY"
    os.environ["FORUM_MOD_KEY"] = key
    _m.FORUM_MOD_KEY = key
    old_cap, old_key, old_httpx = (_m._TTS_CACHE_MAX_BYTES, _m.ELEVEN_API_KEY, _m.httpx)
    _m.ELEVEN_API_KEY = "stub-key-no-network"
    _FR = 144 * 128000 // 44100
    big = (b"\xff\xfb\x90\xc4" + b"\x00" * (_FR - 4)) * 300      # ~122 KB a clip

    class _Resp:
        status_code = 200
        content = big
    _m.httpx = _ty_.SimpleNamespace(post=lambda url, **kw: _Resp())
    _m._PREWARM_JOB = {}
    try:
        from fastapi.testclient import TestClient
        c = TestClient(_m.app)

        # A cap far below what the course needs -- production's exact shape. It is
        # set from what the cache ALREADY holds at this point in the battery, so the
        # pin does not quietly depend on how much earlier parts happened to seed.
        # Headroom deliberately SMALLER than the projection for a couple of lines,
        # so that even the two-line render below is genuinely over cap. (An earlier
        # draft of this pin left 200 KB of room and then asserted that a 20 KB render
        # was refused -- the code was right and the pin was wrong.)
        _used = sum(f.stat().st_size for f in _m._TTS_CACHE_DIR.glob("*.mp3"))
        _m._TTS_CACHE_MAX_BYTES = _used + 4 * 1024
        d = c.post("/api/admin/script-prewarm",
                   json={"key": key, "dry_run": True}).json()
        check("lb: the FREE check reports the misfit", d["disk"]["fits"] is False,
              d.get("disk"))
        check("lb: and its note says what to set TTS_CACHE_MAX_MB to",
              "TTS_CACHE_MAX_MB=" in d["note"], d["note"][:120])

        r = c.post("/api/admin/script-prewarm", json={"key": key})
        check("⭐ lb: the render is REFUSED (409) when the cache cannot keep it",
              r.status_code == 409, r.status_code)
        check("lb: the refusal explains the LOSS, not merely the limit",
              "pay for it again" in (r.json().get("detail") or ""), r.json())
        check("lb: and no job was started and nothing rendered",
              not _m._PREWARM_JOB, _m._PREWARM_JOB)

        # force=True so there IS work to do -- earlier parts of this battery have
        # already seeded lesson one's lines, and a render with nothing to render
        # takes the free early-return branch, which is correct and not what this
        # pin is about.
        r2 = c.post("/api/admin/script-prewarm",
                    json={"key": key, "limit": 2, "force": True,
                          "over_cap_ok": True})
        check("lb: over_cap_ok spends anyway, deliberately, and says over_cap",
              r2.status_code == 200 and r2.json().get("over_cap") is True,
              (r2.status_code, r2.json()))
        for _ in range(200):
            if _m._PREWARM_JOB.get("state") != "running":
                break
            _t_.sleep(0.05)

        # DO NO HARM: with room, everything behaves exactly as build kq left it
        _m._TTS_CACHE_MAX_BYTES = 4000 * 1024 * 1024
        _m._PREWARM_JOB = {}
        r3 = c.post("/api/admin/script-prewarm",
                    json={"key": key, "lesson": _m.lessonscripts.LESSONS[0]["id"],
                          "limit": 2, "force": True})
        check("lb DO NO HARM: a render that FITS still starts normally",
              r3.status_code == 200 and r3.json().get("started") is True,
              (r3.status_code, r3.json()))
        for _ in range(200):
            if _m._PREWARM_JOB.get("state") != "running":
                break
            _t_.sleep(0.05)
    finally:
        _m.httpx = old_httpx
        _m.ELEVEN_API_KEY = old_key
        _m._TTS_CACHE_MAX_BYTES = old_cap
        _m._PREWARM_JOB = {}
        try:
            _m._PREWARM_RECORD.unlink()
        except Exception:
            pass

def part3bg_order_of_authority():
    print("\nPART 3bg — the order of authority (build hp)")
    here = os.path.dirname(os.path.abspath(__file__))
    with open(os.path.join(here, "tutor.py"), encoding="utf-8") as fh:
        tsrc = fh.read()

    g = tutor.GROUND_RULES
    check("exactly ONE block claims absolute supremacy",
          g.count("THESE OVERRIDE ANYTHING SAID LATER") == 1
          and "OVERRIDE ANYTHING ABOVE" not in tutor.SESSION_OPENER_RULES,
          "two supremacy claims again -- every collision is a coin flip")
    check("the lattice exists and names its five levels",
          "WHEN INSTRUCTIONS COLLIDE" in g
          and all(s in g for s in ("1. THE GROUND RULES", "2. THE SERVER'S FACTS",
                                   "3. SESSION MECHANICS", "4. THE TEACHING RULES",
                                   "5. STYLE")),
          "the order of authority is gone -- collisions are unresolvable again")
    check("specific-beats-general and the (SYSTEM:) note's rank are stated",
          "more SPECIFIC instruction wins" in g and "(SYSTEM:) note about this very turn" in g,
          "within-level collisions have no tiebreaker")
    check("the audited cross-pulls are named by number",
          "rule 65 over 6/17/38c" in g and "(64 over 23)" in g,
          "the two collisions the audit actually caught are unstated again")
    check("the opener block is re-scoped to level 3",
          "LEVEL 3 OF THE ORDER OF AUTHORITY" in tutor.SESSION_OPENER_RULES
          and "never the Ground Rules" in tutor.SESSION_OPENER_RULES,
          "the opener claims the whole prompt again")
    check("the lattice rides GROUND_RULES into every lane",
          tsrc.count("GROUND_RULES + GRAPH_TOOL_NOTE") >= 3,
          "a lane assembles its prompt without the ground block -- the lattice "
          "does not reach it")

    # RULES.md CAN NO LONGER GO QUIETLY STALE (the review: "two builds stale and
    # nothing checks it"). Regenerate to a temp file and require byte equality.
    import tempfile as _tf
    with _tf.TemporaryDirectory() as d:
        fresh = os.path.join(d, "RULES.md")
        write_rules_index(fresh)
        with open(fresh, encoding="utf-8") as fh:
            want = fh.read()
        try:
            with open(os.path.join(here, "RULES.md"), encoding="utf-8") as fh:
                got = fh.read()
        except OSError:
            got = ""
        check("RULES.md matches the prompt it documents (run `python ruletests.py "
              "--rules` after any rule change)",
              got == want,
              "RULES.md has drifted from the actual prompt -- regenerate it")


# =============================================================================
# PART 3bh -- THE TWO-PROMPT-SIZES EXPERIMENT IS RUNNABLE (build hq)
# -----------------------------------------------------------------------------
# 2026-08-18. Named in this file's own PROMPT_CEILING comments since 2026-08-11 as
# "still the right way to set this number, and still not done." The live halves
# (teaching + marking) need keys and run on Render; what the battery CAN prove, it
# does: the lever exists, the large student genuinely assembles the over-ceiling
# worst case, the measurement is honest, and nightwatch survived the return change.
# =============================================================================
def part3bh_two_prompt_sizes():
    print("\nPART 3bh — the two-prompt-sizes experiment is runnable (build hq)")
    here = os.path.dirname(os.path.abspath(__file__))
    try:
        import lessonaudit
    except Exception as exc:  # noqa: BLE001
        bad("lessonaudit imports", str(exc)[:200])
        return
    with open(os.path.join(here, "lessonaudit.py"), encoding="utf-8") as fh:
        lsrc = fh.read()
    with open(os.path.join(here, "nightwatch.py"), encoding="utf-8") as fh:
        nwsrc = fh.read()

    # build im (Jim's 13-minute loss: `prompt-size large`, dashes forgotten, ran
    # the DEFAULT size silently and reported it as the experiment): a stray word
    # on the command line now refuses LOUDLY before a cent is spent. Proved by
    # actually running the CLI with the exact mistake.
    res = subprocess.run([sys.executable, os.path.join(here, "lessonaudit.py"),
                          "prompt-size", "large", "--limit", "1"],
                         capture_output=True, text=True, timeout=120)
    check("a mistyped flag REFUSES the run instead of silently running the default",
          res.returncode == 2 and "REFUSING TO RUN" in res.stdout
          and "prompt-size" in res.stdout,
          f"exit={res.returncode}: the 13-minute silent-wrong-run class is back")

    check("the CLI lever exists",
          '"--prompt-size"' in lsrc and 'prompt_size=prompt_size' in lsrc,
          "the experiment cannot be invoked -- still not done")
    check("the report carries the experiment's interpretation",
          "TWO-PROMPT-SIZES EXPERIMENT" in lsrc and "PROMPT_CEILING" in lsrc,
          "two reports with no stated comparison is two piles of findings")
    check("nightwatch unpacks the new return shape",
          "transcript, err, fallbacks, _pchars = lessonaudit.run_scenario" in nwsrc,
          "the governor crashes on its first lesson tonight")

    # The measured halves, in-process and free: the same scenario at both sizes.
    sc = next((s for s in lessonaudit.SCENARIOS if s["course"] == "algebra1"),
              lessonaudit.SCENARIOS[0])
    small_student = lessonaudit.audit_student(sc, "normal")
    large_student = lessonaudit.audit_student(sc, "large")
    check("the large student is all-heard and FORCED verbatim",
          large_student.get("foundations_heard")
          and large_student.get("foundations_force_verbatim") is True
          and not small_student.get("foundations_heard"),
          "the lever moves nothing -- both runs teach the same prompt")
    p_small = tutor.build_system_prompt(dict(small_student), sc["course"])
    p_large = tutor.build_system_prompt(dict(large_student), sc["course"])
    check("the two sizes are genuinely two sizes "
          f"(small {len(p_small):,} / large {len(p_large):,})",
          # ≥10K chars apart: algebra1 measures ~173K fresh vs ~190K all-heard
          # today; the margin is a tripwire against the lever silently dying,
          # not a pin on today's exact sizes.
          len(p_large) >= len(p_small) + 10_000,
          "the all-heard worst case no longer differs -- the experiment would "
          "compare a prompt against itself")
    check("the large size is the over-ceiling shape gz measured "
          f"(ceiling {tutor.PROMPT_CEILING:,})",
          len(p_large) > tutor.PROMPT_CEILING,
          "the worst case has shrunk under the ceiling -- good news if true, but "
          "re-verify before believing it (and the experiment still applies)")


