# =============================================================================
# PART 3cp -- THE TURN CLOCK (build jm, 2026-08-20)
# -----------------------------------------------------------------------------
# Jim: "what I'm really looking for is a responsive accurate application above cost."
# Before jm the only measurement of turn time that had ever existed was Jim counting --
# "five to eight seconds". Now every refereed turn records ms_total / ms_model /
# ms_retry on its usage_log row, and ms_retry gives Lever 1 of the responsiveness
# proposal a number instead of an argument.
#
# TWO FAILURE MODES ARE PINNED, AND THE SECOND IS THE DANGEROUS ONE:
#   (1) the clock stops recording -- caught by the source pins below;
#   (2) THE CLOCK LIES. An untimed row averaged in as an instant turn would make the
#       app look faster the more of it went unmeasured. usage_stats must drop
#       ms_total == 0, and that is proved against a REAL database, not by reading code.
# =============================================================================
_JM_CLOCK = r"""
import os, sys, json
os.environ["DATABASE_URL"] = "sqlite:///" + sys.argv[1]
sys.path.insert(0, sys.argv[2])
import store
store.init()
assert store.enabled(), store.status()
from sqlalchemy import inspect
out = {}
cols = {c["name"] for c in inspect(store._engine).get_columns("usage_log")}
out["cols"] = sorted(c for c in ("ms_total", "ms_model", "ms_retry", "ms_critic")
                     if c in cols)
def brain(**kw):
    store.log_usage(kind="brain", code="C1", course="prealgebra", mode="lesson",
                    model="m", **kw)
brain(attempts=1, verify_status="ok",         ms_total=2000,  ms_model=1800, ms_retry=0)
brain(attempts=2, verify_status="fixed",      ms_total=6000,  ms_model=5200, ms_retry=4000)
brain(attempts=3, verify_status="unresolved", ms_total=10000, ms_model=9000, ms_retry=8000)
brain(attempts=1, verify_status="ok")                      # never timed (pre-jm row)
brain(attempts=1, verify_status="ok", ms_total=-5, ms_model=-5, ms_retry=-5)  # rubbish
# build jp: the SECOND OPINION's own rows -- kind="critic", which every brain figure
# on the cost card filters OUT. Two calls, and one timed brain turn that paid for them.
store.log_usage(kind="critic", code="C1", course="prealgebra", mode="lesson",
                model="claude-opus-5", input_tokens=3000, output_tokens=120,
                attempts=1, verify_status="critic")
store.log_usage(kind="critic", code="C1", course="prealgebra", mode="lesson",
                model="claude-opus-5", input_tokens=3000, output_tokens=120,
                attempts=1, verify_status="critic")
brain(attempts=1, verify_status="ok", ms_total=4000, ms_model=2000, ms_retry=0,
      ms_critic=1500)
st = store.usage_stats(7)
for k in ("brain_calls", "timed_turns", "ms_sampled", "ms_avg", "ms_median", "ms_p90",
          "ms_max", "ms_model_avg", "ms_retry_avg", "ms_retry_share",
          "critic_calls", "critic_input_tokens", "critic_output_tokens",
          "ms_critic_avg", "ms_critic_share",
          "sized_turns", "out_chars_avg", "out_spoken_avg", "out_tags_avg",
          "out_spoken_share"):
    out[k] = st.get(k)
print(json.dumps(out))
"""


def part3cp_turn_clock():
    print("\nPART 3cp — the turn clock (build jm)")
    here = os.path.dirname(os.path.abspath(__file__))
    import tempfile as _tf, json as _json

    # ---- 1. THE ARITHMETIC, with no database in sight -----------------------
    try:
        import store as _st
    except Exception as exc:  # noqa: BLE001
        bad("store imports for the turn clock", str(exc))
        return
    ts = _st._timing_summary
    check("turn clock: an odd-length median is the middle value",
          ts([(1, 0, 0), (3, 0, 0), (2, 0, 0)])["ms_median"] == 2,
          "the median is not sorting -- every latency number on /admin is wrong")
    check("turn clock: an even-length median is the mean of the middle two",
          ts([(2, 0, 0), (4, 0, 0)])["ms_median"] == 3, "median arithmetic")
    # NOTE, recorded because the first version of this check was WRONG and the code was
    # right (the hi/hh lesson: an expectation can be wrong when the data is fine). For
    # 1..10 the NEAREST-RANK p90 is 9, not 10 -- 10 is p100. What p90 must never do is
    # collapse onto the median or run away to the max.
    _ten = ts([(i, 0, 0) for i in range(1, 11)])
    check("turn clock: p90 sits in the slow tail, between the median and the slowest",
          _ten["ms_p90"] == 9 and _ten["ms_median"] == 6 and _ten["ms_max"] == 10,
          f"{_ten} -- p90 is the number that describes the child who waited longest; "
          "it must not collapse to the median")
    z = ts([(0, 0, 0), (0, 9, 9), (4, 1, 1)])
    check("turn clock: an UNTIMED row is dropped, never averaged in as instant",
          z["ms_sampled"] == 1 and z["ms_avg"] == 4,
          "an unmeasured turn counted as 0ms makes the app look faster the more of it "
          "goes unmeasured -- the one way this instrument could lie")
    e = ts([])
    check("turn clock: nothing measured yields zeros, not a crash",
          e["ms_sampled"] == 0 and e["ms_median"] == 0, "empty window must be survivable")
    check("turn clock: rubbish rows cannot raise",
          ts([(None, None, None), ("x", "y", "z"), (5, None, None)])["ms_sampled"] == 1,
          "a malformed row must never 500 the dashboard")
    check("turn clock: the retry share is a percentage of total turn time",
          ts([(1000, 0, 0), (1000, 0, 500)])["ms_retry_share"] == 25.0,
          "ms_retry_share is Lever 1 in one number -- it must be retry/total")

    # ---- 2. THE WIRING (source) ---------------------------------------------
    with open(os.path.join(here, "tutor.py"), encoding="utf-8") as fh:
        tsrc = fh.read()
    body = tsrc.split("def _create_verified(")[-1].split("\ndef ")[0]
    check("turn clock: _create_verified starts the clock",
          'tokens["_t0"] = time.monotonic()' in body,
          "no start time -- ms_total would be 0 on every turn")
    check("turn clock: the retry marker is set when attempt 2 begins",
          'if attempt == 2 and "_t_retry0" not in tokens:' in body,
          "ms_retry would stay 0 however many drafts were thrown away")
    check("turn clock: EVERY model call in the turn is timed",
          "_timed_create_full(" in body and "= _create_full(" not in body,
          "a bare _create_full inside _create_verified is time that vanishes from "
          "ms_model -- the split would silently blame the referees for it")
    check("turn clock: the usage row carries the three numbers",
          "ms_total=ms_total" in tsrc and "def _turn_ms" in tsrc,
          "_log_brain_usage stopped passing the clock to the store")
    with open(os.path.join(here, "store.py"), encoding="utf-8") as fh:
        ssrc = fh.read()
    check("turn clock: the additive migration exists AND is called at init",
          "def _migrate_usage_log_timing" in ssrc
          and ssrc.count("_migrate_usage_log_timing()") >= 2,
          "an existing Postgres usage_log would never gain the columns, and every "
          "write would fail on a live database")
    with open(os.path.join(here, "static", "admin.html"), encoding="utf-8") as fh:
        asrc = fh.read()
    for label, needle in (("the median-turn tile", '"Median turn"'),
                          ("the model-time tile", '"Waiting on the model"'),
                          ("the retry-cost tile", '"Lost to retries"'),
                          ("the ms formatter", "function secs(ms)"),
                          ("the retry-share colouring", "var retryCls")):
        check(f"  turn clock: /admin shows {label}", needle in asrc,
              "the number is recorded but nobody can read it")

    # ---- 3. THE PROOF, on a real database -----------------------------------
    try:
        import sqlalchemy  # noqa: F401
    except Exception:  # noqa: BLE001
        skip("turn-clock database proof", "sqlalchemy not installed here")
        return
    with _tf.TemporaryDirectory() as d:
        script = os.path.join(d, "clock.py")
        with open(script, "w", encoding="utf-8") as fh:
            fh.write(_JM_CLOCK)
        res = subprocess.run([sys.executable, script, os.path.join(d, "jm.db"), here],
                             capture_output=True, text=True, timeout=300)
        line = (res.stdout.strip().splitlines() or [""])[-1]
        try:
            v = _json.loads(line)
        except Exception:  # noqa: BLE001
            bad("turn-clock database proof ran", (res.stderr or res.stdout).strip()[:300])
            return
        check("turn clock: a fresh usage_log has all FOUR timing columns",
              v.get("cols") == ["ms_critic", "ms_model", "ms_retry", "ms_total"],
              str(v.get("cols")))
        check("turn clock: six turns logged, only FOUR of them timed",
              v.get("brain_calls") == 6 and v.get("timed_turns") == 4,
              f"{v} -- an untimed or clamped row leaked into the timed population")
        # NOTE (the third time today, and the lesson is the same one): my EXPECTATION
        # was wrong and the code was right. The four timed turns are 2,000 / 4,000 /
        # 6,000 / 10,000 ms, so the even-length median is (4,000 + 6,000) / 2 = 5,000.
        check("turn clock: median 5.0s, slowest 10.0s, average 5.5s",
              (v.get("ms_median"), v.get("ms_max"), v.get("ms_avg"))
              == (5000, 10000, 5500), str(v))
        check("turn clock: retries average 3.0s and are 54.5% of all turn time",
              v.get("ms_retry_avg") == 3000 and v.get("ms_retry_share") == 54.5,
              f"{v} -- Lever 1's number is wrong")
        check("turn clock: a negative duration is clamped, never stored",
              v.get("ms_max") == 10000 and v.get("timed_turns") == 4,
              "rubbish from a caller must not poison an average")
        # ---- build jp: THE SECOND OPINION ----
        check("second opinion: critic calls are counted, and NOT as tutor turns",
              v.get("critic_calls") == 2 and v.get("brain_calls") == 6,
              f"{v} -- a critic row is kind='critic'; if it ever lands in brain_calls "
              "the turn count and every per-turn share become wrong")
        check("second opinion: its tokens are aggregated for pricing",
              v.get("critic_input_tokens") == 6000
              and v.get("critic_output_tokens") == 240,
              f"{v} -- an Opus call on every draft with no token total is a bill "
              "nobody can see")
        check("second opinion: its seconds are attributed to it, not to overhead",
              v.get("ms_critic_avg") == 375 and v.get("ms_critic_share") == 6.8,
              f"{v} -- 1500ms over 4 timed turns is 375 average, 6.8% of 22,000ms")



# =============================================================================
# PART 3cq -- "WE WRITE X, WHICH IS READ AS X" (build jn, 2026-08-20)
# -----------------------------------------------------------------------------
# From one live precalc lesson of Jim's. The screen read:
#
#     "We write f of x, which is read as f of x."
#
# A sentence whose entire job is to separate the SYMBOL from its READING, with the
# reading on both sides. It came from an AUTHORED foundation script, spoken verbatim --
# not from the model.
#
# ⭐ THE PART WORTH REMEMBERING: writing "f(x)" does NOT fix it. speech-text.js
# forSpeech() converts f(x) -> "f of x" before the TTS engine ever sees it, which is
# right for the ear and makes the corrected sentence a tautology AGAIN out loud. In a
# voice-first product the screen is only half the check. So this part normalises BOTH
# sides the way the ear will hear them before comparing -- and it therefore fails the
# naive fix as loudly as the original defect.
#
# The cure is to name the notation in words that survive the transform, which the
# "function notation" script one entry below had been doing correctly all along.
# =============================================================================
_JN_TAUT = re.compile(
    r"\bwe write\b[:\s]*(.{1,70}?)[,;]?\s*(?:which is |and it is |and is |and )?"
    r"(?:read|said|pronounced|spoken|say)\w*\s*(?:it\s*)?(?:out loud\s*|aloud\s*)?"
    r"(?:as|:)\s*(.{1,70}?)\s*[.,;]", re.I)


def _jn_as_heard(s):
    """What the EAR gets. Mirrors speech-text.js forSpeech()'s f(x) -> 'f of x' rule,
    then strips everything that cannot be heard, so "f(x)" and "f of x" compare EQUAL."""
    s = re.sub(r"([A-Za-z])\s*\(\s*([A-Za-z0-9]+)\s*\)", r"\1 of \2", str(s or ""))
    return " ".join(re.sub(r"[^a-z0-9 ]+", " ", s.lower()).split())


def part3cq_notation_tautology():
    print("\nPART 3cq — \"we write X, which is read as X\" (build jn)")
    try:
        import foundations as _F
    except Exception as exc:  # noqa: BLE001
        bad("foundations imports", str(exc))
        return

    # ---- 1. THE DETECTOR ITSELF, on known inputs -----------------------------
    def taut(text):
        m = _JN_TAUT.search(text)
        if not m:
            return None
        a, b = _jn_as_heard(m.group(1)), _jn_as_heard(m.group(2))
        return bool(a) and a == b
    check("tautology check: the sentence a child actually read is caught",
          taut("We write f of x, which is read as f of x, and it means the output.") is True,
          "the defect that shipped would ship again")
    check("tautology check: the NAIVE fix is caught too (it is a tautology in the EAR)",
          taut("We write f(x), which is read as f of x, and it means the output.") is True,
          "forSpeech turns f(x) into 'f of x' before the TTS engine sees it -- a "
          "screen-only fix leaves the child HEARING the same broken sentence")
    check("tautology check: naming the notation in words is clean",
          taut("We write it with the letter f and the input tucked inside parentheses, "
               "and you say the whole thing out loud as f of x.") is None,
          "the cure must not be flagged as the disease")
    check("tautology check: a genuinely different reading is clean",
          taut("We write dy/dx, which is read as the derivative of y with respect to x.")
          is False, "a real notation lesson must pass")
    check("tautology check: prose with no such claim is untouched",
          taut("A function is a rule that takes one input.") is None,
          "the pattern must not reach into ordinary teaching")

    # ---- 2. THE CORPUS -------------------------------------------------------
    hits = []
    scanned = 0
    for course, items in getattr(_F, "FOUNDATIONS", {}).items():
        for it in items:
            scanned += 1
            for m in _JN_TAUT.finditer(it.get("say") or ""):
                a, b = _jn_as_heard(m.group(1)), _jn_as_heard(m.group(2))
                if a and a == b:
                    hits.append(f"{course}/{it.get('term')}: "
                                f"{m.group(1)!r} == {m.group(2)!r} (as heard)")
    check(f"no authored script says \"we write X, which is read as X\" "
          f"({scanned} scripts scanned, as HEARD)",
          not hits, f"{hits[:3]} -- a sentence that exists to separate the symbol from "
                    "its reading, with the reading on both sides")
    # The specific script this build fixed, pinned by its cure rather than its disease.
    try:
        fn = next(it for it in _F.FOUNDATIONS["precalc"] if it.get("term") == "function")
        say = fn.get("say") or ""
        check("the precalc 'function' script names the notation in words",
              "tucked inside parentheses" in say and "out loud as f of x" in say,
              "the 2026-08-20 wording was reverted -- the tautology is back")
        check("the precalc 'function' script still shows the real f(x) on the board",
              any('fname="f"' in b for b in (fn.get("board") or [])),
              "the prose describes notation the board no longer displays -- the child "
              "is told how to say a symbol they never see")
    except StopIteration:
        bad("the precalc 'function' script exists", "it was renamed or removed")



# =============================================================================
# PART 3cr -- THE REFEREE CAN HEAR WORDS (build jo, 2026-08-20)
# -----------------------------------------------------------------------------
# The first real reading of /admin (jj's by-name table + jm's clock) measured 206
# retries on 692 turns -- 29.8% -- and named the culprit: `unspoken`, rule 44's
# referee, fired on 4.3% of turns and caused most of the 21 replies that shipped WITH
# an unresolved finding. Its pass-through details named the boards, and every one of
# those numbers was invisible to it when read aloud PROPERLY, because _EQ_NUMWORD
# stops at 20 plus the round tens.
#
# The tutor read the problem aloud exactly as rule 48 demands. The referee could not
# hear it. Three attempts burned, flawed reply shipped. Build iz's phantom, second
# costume: UNRESOLVABLE BY CONSTRUCTION.
#
# ⚠️ THIS PART EXISTS AS MUCH TO PROTECT gk AND gw AS TO PROVE jo. Those two builds
# narrowed this function on purpose, from real audit findings, and a fix that widened
# it carelessly would hand a listening child a problem they only ever saw written down
# -- which is the whole reason rule 44 exists. Both directions are pinned below, and
# the five boards are the REAL ones from the live pass-through list, verbatim.
# =============================================================================
def part3cr_referee_hears_words():
    print("\nPART 3cr — the referee can hear words (build jo)")
    sn = getattr(tutor, "_spoken_numbers", None)
    if sn is None:
        bad("_spoken_numbers exists", "the compound number-word reader is gone")
        return

    # ---- 1. THE READER --------------------------------------------------------
    for label, text, want in (
            ("a compound hundred", "one hundred forty four", {144}),
            ("two runs, separated by an operator", "three hundred plus five hundred",
             {300, 500}),
            ("a compound ten", "twenty five", {25}),
            ("hyphenated", "twenty-five", {25}),
            ("British 'and' after a scale", "one hundred and eighty", {180}),
            ("thousands", "two thousand three hundred", {2300}),
            ("no number words at all", "nothing numeric here", set())):
        check(f"  number words: {label}", sn(text) == want, f"{sn(text)} != {want}")
    # THE TWO THAT MUST NOT MERGE. A run has to END at its separator, or gk's exact
    # sentence would start reading as one enormous number.
    check("  number words: an operator BREAKS the run (3 + 1 is never 31)",
          sn("three plus one really is four") == {1, 3, 4},
          "adjacent numbers merged across a separator -- gk's sentence would be "
          "misread and the fraction bug could come back through the side door")
    check("  number words: a bare 'and' does NOT continue a run",
          sn("three and four") == {3, 4},
          "'three and four' read as 34 -- 'and' may only bridge after a scale word")
    check("  number words: rubbish input yields an empty set, never a raise",
          sn(None) == set() and sn(12345) == set(), "the reader must fail open")

    # ---- 2. THE FIVE BOARDS FROM THE LIVE PASS-THROUGH LIST --------------------
    for board, prose in (
            ("0.10 x 80 = ?", "What is ten percent of eighty?"),
            ("300 + 500 = ?", "What is three hundred plus five hundred?"),
            ("144 + ? = 180", "One hundred forty four plus what makes one hundred eighty?"),
            ("130 + ? = 180", "One hundred thirty plus what gives us one hundred eighty?"),
            ("c = sqrt(25) = ?", "So c equals the square root of twenty five.")):
        check(f"  heard aloud: {board}", tutor._pq_spoken_covers(prose, board) is True,
              "this exact board burned all three attempts in production and shipped "
              "the flawed reply anyway")

    # ---- 3. gk AND gw STILL REJECT WHAT THEY WERE WRITTEN TO REJECT ------------
    check("gk survives: 'three plus one really is four' does NOT read 3/4 + 1/4",
          tutor._pq_spoken_covers(
              "Good job adding the tops — three plus one really is four!",
              "3/4 + 1/4 = ?") is False,
          "the 2026-08-16 fractions bug is back: a child is asked about a problem "
          "they only ever saw written down")
    check("gw survives: 'try one with a similar setup' does NOT read 1.35",
          tutor._pq_spoken_covers(
              "Let us try one with a similar setup, different-length decimals again.",
              "2.6 + 1.35 = ?") is False,
          "the 2026-08-17 decimal bug is back -- the '1' inside the word 'one' is "
          "not a reading of 1.35")
    check("a decimal read as a decimal still counts",
          tutor._pq_spoken_covers("two point six plus one point three five",
                                  "2.6 + 1.35 = ?") is True,
          "the honest reading must still pass")

    # ---- 4. THE PERCENT DOOR IS NARROW ---------------------------------------
    check("percent door: the word 'percent' is REQUIRED",
          tutor._pq_spoken_covers("What is ten of eighty?", "0.10 x 80 = ?") is False,
          "any sentence containing 'ten' would open the decimal branch -- the door "
          "must need the word that makes it a reading")
    check("percent door: the value must be EXACT",
          tutor._pq_spoken_covers("about twenty percent of it", "0.10 x 80 = ?") is False,
          "a different percentage is not a reading of this number")
    check("percent door: digits work too",
          tutor._pq_spoken_covers("what is 10 percent of eighty?",
                                  "0.10 x 80 = ?") is True,
          "a tutor who says the digits has still read it aloud")



